(function(){'use strict';
const KEY='nawaf-hq-v5';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason='v12'){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function icon(path){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>`}
const I={bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',activity:'M3 12h4l2-6 4 12 2-6h6',retry:'M20 11a8 8 0 1 0 2 5M20 4v7h-7',clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 5v5l3 2',finance:'M3 18h18M6 15V9m6 6V5m6 10v-4M4 5l5 3 4-5 7 4'};
function ensureDock(){let d=$('.v12-dock');if(d)return d;d=document.createElement('div');d.className='v12-dock';d.innerHTML=`<button data-v12-notify title="التنبيهات">${icon(I.bell)}<span class="v12-badge">0</span></button><button data-v12-activity title="النشاط">${icon(I.activity)}</button><button data-v12-recovery title="المهام العالقة">${icon(I.retry)}</button><button data-v12-finance title="المحلل المالي">${icon(I.finance)}</button>`;document.body.appendChild(d);d.addEventListener('click',e=>{if(e.target.closest('[data-v12-notify]'))openNotifications();if(e.target.closest('[data-v12-activity]'))openActivity();if(e.target.closest('[data-v12-recovery]'))openRecovery();if(e.target.closest('[data-v12-finance]'))window.NawafFinance?.open?.()});return d}
function ensurePanel(){let p=$('.v12-panel');if(p)return p;p=document.createElement('aside');p.className='v12-panel';p.innerHTML='<div class="v12-panel-head"><div><small>NAWAF HQ</small><h3></h3></div><button data-v12-close>×</button></div><div class="v12-panel-body"></div>';document.body.appendChild(p);p.querySelector('[data-v12-close]').onclick=()=>p.classList.remove('show');return p}
function showPanel(title,html){const p=ensurePanel();p.querySelector('h3').textContent=title;p.querySelector('.v12-panel-body').innerHTML=html;p.classList.add('show');return p}
function waiting(){const s=read();return (s.tasks||[]).filter(t=>t.status==='WAITING_FOR_NAWAF'||(t.status==='READY'&&t.blockedReason));}
function updateBadge(){const d=ensureDock(),n=waiting().length,b=d.querySelector('.v12-badge');b.textContent=String(n);b.style.display=n?'grid':'none'}
function openNotifications(){const s=read(),items=[...waiting().map(t=>({title:t.title,sub:t.blockedReason||'تحتاج قرارك',kind:'warn'})),...(s.tasks||[]).filter(t=>t.status==='COMPLETED').slice(0,5).map(t=>({title:t.title,sub:'اكتملت المهمة',kind:'ok'}))];showPanel('التنبيهات',items.length?items.map(x=>`<article class="v12-note ${x.kind}"><b>${esc(x.title)}</b><small>${esc(x.sub)}</small></article>`).join(''):'<div class="v12-empty">ما عندك تنبيهات حالياً.</div>')}
function openActivity(){const s=read(),items=(s.activity||[]).slice(0,40);showPanel('سجل النشاط',items.length?items.map(a=>`<article class="v12-activity"><span></span><div><b>${esc(a.text||'نشاط')}</b><small>${a.at?new Date(a.at).toLocaleString('ar-SA'):''}</small></div></article>`).join(''):'<div class="v12-empty">ما فيه نشاط محفوظ.</div>')}
function openRecovery(){const s=read(),now=Date.now(),stuck=(s.tasks||[]).filter(t=>{const ts=Date.parse(t.lastRunAt||t.executionStartedAt||t.createdAt||'');return ['WORKING','RESEARCHING','REVIEWING'].includes(t.status)&&(Number.isFinite(ts)&&now-ts>20*60*1000)}),failed=(s.tasks||[]).filter(t=>t.status==='READY'&&t.blockedReason);const all=[...stuck,...failed.filter(x=>!stuck.some(y=>y.id===x.id))];const p=showPanel('استعادة المهام',all.length?all.map(t=>`<article class="v12-recover" data-v12-task="${esc(t.id)}"><div><b>${esc(t.title)}</b><small>${esc(t.blockedReason||'يبدو أن المهمة متوقفة منذ فترة')}</small></div><button type="button" data-v12-retry="${esc(t.id)}">إعادة المحاولة</button></article>`).join(''):'<div class="v12-empty">ممتاز، ما فيه مهام عالقة.</div>');p.querySelectorAll('[data-v12-retry]').forEach(b=>b.onclick=()=>retryTask(b.dataset.v12Retry))}
function retryTask(id){const s=read(),t=(s.tasks||[]).find(x=>x.id===id);if(!t)return;t.status='READY';t.progress=0;delete t.executionStartedAt;delete t.blockedReason;t.lastRunAt=new Date().toISOString();const e=(s.employees||[]).find(x=>x.id===t.employeeId);if(e){e.status='READY';e.task=t.title}s.activity=Array.isArray(s.activity)?s.activity:[];s.activity.unshift({id:'a'+Date.now().toString(36),text:`إعادة محاولة: ${t.title}`,type:'REAL',at:new Date().toISOString()});write(s,'task-retry');window.NawafProjectExecutor?.scan?.();window.NawafAgents?.runTask?.(id)?.catch?.(()=>{});openRecovery()}
function injectFinanceSummary(){if($('.v12-fin-summary'))return;const s=read(),fin=(s.tasks||[]).filter(t=>t.domain==='FINANCE'),host=$('.v9-control-strip');if(!host)return;const done=fin.filter(t=>t.status==='COMPLETED').length,wait=fin.filter(t=>t.status==='WAITING_FOR_NAWAF').length;const box=document.createElement('div');box.className='v12-fin-summary';box.innerHTML=`${icon(I.finance)}<span><b>الاستثمار</b><small>${fin.length} تحليلات • ${done} مكتمل • ${wait} ينتظر</small></span>`;box.onclick=()=>window.NawafFinance?.open?.();host.appendChild(box)}
function injectTaskAge(){const s=read(),map=new Map((s.tasks||[]).map(t=>[t.id,t]));$$('.v8-row[data-task]').forEach(r=>{if(r.querySelector('.v12-age'))return;const t=map.get(r.dataset.task),ts=Date.parse(t?.createdAt||'');if(!Number.isFinite(ts))return;const mins=Math.max(1,Math.floor((Date.now()-ts)/60000));const el=document.createElement('small');el.className='v12-age';el.textContent=mins<60?`منذ ${mins} د`:`منذ ${Math.floor(mins/60)} س`;r.appendChild(el)})}
function injectAutoRefresh(){if($('[data-v12-refresh]'))return;const actions=$('.v8-actions');if(!actions)return;const b=document.createElement('button');b.type='button';b.className='v8-btn';b.dataset.v12Refresh='1';b.innerHTML=`${icon(I.clock)}<span>تحديث</span>`;b.onclick=async()=>{b.disabled=true;try{await window.HQCloud?.pull?.();window.NawafHQV11?.checkHealth?.(true)}finally{setTimeout(()=>b.disabled=false,700)}};actions.prepend(b)}
function improveFinance(){const original=window.NawafFinance?.open;if(!original||window.NawafFinance.__v12)return;window.NawafFinance.__v12=true;window.NawafFinance.open=function(){original();setTimeout(()=>{const m=$('#finance-modal');if(!m)return;m.classList.add('v12-finance-modal');const form=m.querySelector('#finance-form');if(form&&!form.querySelector('.v12-fin-guide')){const g=document.createElement('div');g.className='v12-fin-guide v9-full';g.innerHTML='<b>منهج راكان</b><span>1) البيانات الأساسية  2) النمو والأرباح  3) التقييم  4) المحفزات  5) المخاطر  6) السيناريوهات  7) الخلاصة</span>';form.insertBefore(g,form.firstChild)}} ,20)}}
function enhance(){ensureDock();updateBadge();injectFinanceSummary();injectTaskAge();injectAutoRefresh();improveFinance()}
let timer;const obs=new MutationObserver(()=>{clearTimeout(timer);timer=setTimeout(enhance,100)});function boot(){enhance();obs.observe(document.body,{childList:true,subtree:true});setInterval(updateBadge,5000);window.addEventListener('nawaf:state-updated',()=>setTimeout(()=>{updateBadge();injectTaskAge()},80))}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();window.NawafHQV12={openNotifications,openActivity,openRecovery,retryTask};
})();